#pragma once

#include <random>

// One die roll from 1 to sides. "inline" lets this header be included from several files.
inline int rollDie(int sides)
{
    static std::mt19937 engine{ std::random_device{}() };
    std::uniform_int_distribution<int> roll{ 1, sides };
    return roll(engine);
}

